CREATE OR REPLACE FUNCTION public._notification_dispatch_configuration()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare project_url text; api_key text; internal_secret text; begin
  if to_regclass('vault.decrypted_secrets') is null then
    raise exception 'notification_scheduler_not_configured';
  end if;
  select decrypted_secret into project_url from vault.decrypted_secrets where name = 'collect_notification_project_url';
  select decrypted_secret into api_key from vault.decrypted_secrets where name = 'collect_notification_api_key';
  select decrypted_secret into internal_secret from vault.decrypted_secrets where name = 'collect_notification_internal_secret';
  if project_url is null or project_url !~ '^https://[a-z0-9]{20}\.supabase\.co$'
    or coalesce(length(api_key), 0) < 20 or coalesce(length(internal_secret), 0) < 32
    or api_key ~ '[\r\n]' or internal_secret ~ '[\r\n]' then
    raise exception 'notification_scheduler_not_configured';
  end if;
  return jsonb_build_object('url', project_url || '/functions/v1/dispatch-notifications',
    'headers', jsonb_build_object('Content-Type', 'application/json', 'apikey', api_key, 'x-collect-signature', internal_secret));
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_feature_flag(p_key text, p_enabled boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  normalized_key text := trim(coalesce(p_key, ''));
  normalized_reason text := trim(coalesce(p_reason, ''));
  flag_row feature_flags%rowtype;
begin
  perform assert_admin_permission('feature_flags.manage');

  if normalized_key = '' then
    raise exception 'Feature flag key is required';
  end if;

  if normalized_reason = '' then
    raise exception 'Feature flag change reason is required';
  end if;

  update feature_flags
  set enabled = p_enabled,
      updated_by = auth.uid(),
      updated_reason = normalized_reason,
      updated_at = now()
  where key = normalized_key
  returning * into flag_row;

  if not found then
    raise exception 'Feature flag not found: %', normalized_key;
  end if;

  perform create_audit_log(
    'admin.feature_flag.updated',
    'feature_flag',
    null,
    jsonb_build_object(
      'key', flag_row.key,
      'enabled', flag_row.enabled,
      'reason', normalized_reason
    )
  );

  return jsonb_build_object(
    'ok', true,
    'key', flag_row.key,
    'enabled', flag_row.enabled,
    'updated_at', flag_row.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_sms_receipt_policy(p_collection_id uuid, p_enabled boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  clean_reason text := btrim(coalesce(p_reason, ''));
  policy collect_hybrid.sms_receipt_policies;
begin
  perform public.assert_admin_permission('notifications.manage');
  perform public.assert_admin_permission('collections.moderate');
  if p_collection_id is null or p_enabled is null
     or char_length(clean_reason) not between 8 and 500 then
    raise exception 'Collection, state and audit reason are required';
  end if;
  if not exists (
    select 1 from public.collections collection
    where collection.id = p_collection_id
      and collection.collection_type = 'ikimina'
      and collection.archived_at is null
  ) then
    raise exception 'Active group savings collection required';
  end if;
  insert into collect_hybrid.sms_receipt_policies(
    collection_id, enabled, reason, updated_by
  ) values (
    p_collection_id, p_enabled, clean_reason, auth.uid()
  )
  on conflict (collection_id) do update
  set enabled = excluded.enabled,
      revision = collect_hybrid.sms_receipt_policies.revision + 1,
      reason = excluded.reason,
      updated_by = excluded.updated_by,
      updated_at = clock_timestamp()
  returning * into policy;
  perform public.create_audit_log(
    'collection.sms_receipt_policy.changed', 'collection', p_collection_id,
    jsonb_build_object(
      'enabled', policy.enabled,
      'template_key', policy.template_key,
      'template_version', policy.template_version,
      'revision', policy.revision,
      'reason', clean_reason
    )
  );
  return jsonb_build_object(
    'ok', true, 'collection_id', policy.collection_id,
    'enabled', policy.enabled, 'revision', policy.revision,
    'template_key', policy.template_key,
    'template_version', policy.template_version
  );
end;
$function$

